import{_ as a,o as l,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"CDS Pacific: RBD","description":"","frontmatter":{"title":"CDS Pacific: RBD","date":"2020-04-02T00:00:00.000Z","updated":"2020-04-03T00:00:00.000Z","tags":["Ceph","RBD","Distributed Storage","Storage Cluster","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/CDS_Pacific_-_RBD.md","filePath":"posts/2020/CDS_Pacific_-_RBD.md","lastUpdated":1780459816000}'),r={name:"posts/2020/CDS_Pacific_-_RBD.md"};function o(s,i,n,c,h,d){return l(),t("div",null,[...i[0]||(i[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph-pacific-版本的-rbd-部分讨论" tabindex="-1">会议主题：Ceph Pacific 版本的 RBD 部分讨论 <a class="header-anchor" href="#会议主题-ceph-pacific-版本的-rbd-部分讨论" aria-label="Permalink to &quot;会议主题：Ceph Pacific 版本的 RBD 部分讨论&quot;">​</a></h4><h4 id="会议时间-2020年4月2日-14-00-utc" tabindex="-1">会议时间：2020年4月2日 14:00 UTC <a class="header-anchor" href="#会议时间-2020年4月2日-14-00-utc" aria-label="Permalink to &quot;会议时间：2020年4月2日 14:00 UTC&quot;">​</a></h4><h4 id="参会人员-ceph-研发团队成员及相关领域专家" tabindex="-1">参会人员：Ceph 研发团队成员及相关领域专家 <a class="header-anchor" href="#参会人员-ceph-研发团队成员及相关领域专家" aria-label="Permalink to &quot;参会人员：Ceph 研发团队成员及相关领域专家&quot;">​</a></h4><h4 id="主要议题及讨论内容" tabindex="-1">主要议题及讨论内容： <a class="header-anchor" href="#主要议题及讨论内容" aria-label="Permalink to &quot;主要议题及讨论内容：&quot;">​</a></h4><ol><li><p><strong>RBD 功能特性更新</strong></p><ul><li><strong>Care Buddy 特性</strong>：虽然不直接与 Pacific 版本绑定，但计划在开发周期内完成。</li><li><strong>压缩提示和本地化读取提示</strong>：这些特性旨在优化压缩行为和读取性能。</li><li><strong>异步重构</strong>：涉及 exclusive lock 代码的异步重构，对性能至关重要。</li></ul></li><li><p><strong>性能优化</strong></p><ul><li><strong>librbd 缓存机制</strong>：讨论了对象 ID 的哈希映射缓存，以减少 CPU 使用和提高小工作负载的性能。</li><li><strong>新的 IO 接口</strong>：旨在通过线程池和更快的 IO 处理来提高性能。</li></ul></li><li><p><strong>RBD 与 RGW 集成</strong></p><ul><li>计划通过 RGW 暴露 RBD 快照，实现快照差异的程序化暴露。</li></ul></li><li><p><strong>即时恢复功能</strong></p><ul><li>讨论了从 S3 或 Swift 备份的 RBD 图像进行即时恢复的功能。</li></ul></li><li><p><strong>客户端加密</strong></p><ul><li>讨论在 librbd 中实现客户端侧加密的可能性。</li></ul></li><li><p><strong>RBD NBD 守护进程</strong></p><ul><li>计划实现一个 RBD NBD 守护进程，以适应 Kubernetes 和容器环境的需求。</li></ul></li><li><p><strong>快照协调</strong></p><ul><li>讨论了在创建快照时协调客户端工作负载的可能性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续推进异步重构工作。</li><li>探索和实现 RBD 与 RGW 的集成，以及即时恢复功能。</li><li>研究客户端侧加密的实现。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完成异步重构，并确保其稳定性和性能。</li><li>实现 RBD NBD 守护进程的多设备支持。</li><li>继续研究和开发客户端侧加密功能。</li><li>监控和优化 librbd 的性能。</li></ul><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>会议涵盖了多个关键的 RBD 功能更新和性能优化议题，团队将继续推进这些工作，以确保 Pacific 版本的顺利发布和高质量。</p>',12)])])}const _=a(r,[["render",o]]);export{p as __pageData,_ as default};
